from rest_framework.decorators import api_view, permission_classes
from rest_framework.permissions import IsAuthenticated
from rest_framework.response import Response
from rest_framework import status
from .models import Shipment
from .webhooks import send_outbound_event

@api_view(['POST'])
@permission_classes([IsAuthenticated])
def test_shipment_webhook_dispatch(request):
    shipment_id = request.data.get('shipment_id')
    try:
        shipment = Shipment.objects.get(id=shipment_id, client=request.user.client_account)
    except Shipment.DoesNotExist:
        return Response({'error': 'Shipment not found or access denied'}, status=status.HTTP_404_NOT_FOUND)

    event_payload = {
        'tracking_code': shipment.tracking_code,
        'recipient_name': shipment.recipient_name,
        'delivery_address': shipment.delivery_address,
        'status': shipment.status
    }
    send_outbound_event(user=request.user, event='shipment.updated', payload=event_payload)
    return Response({'status': 'event_dispatched', 'tracking_code': shipment.tracking_code})
